tool_schemas.implementation:
def geocode_address(text, provider=None, idempotency_key=None, **_extra):
    import json, os, datetime, time, uuid, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0502000" if __import__("os").path.isdir("./environment_mix/0502000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    month_bucket = now[:7]

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    ops = _load("geo_operations.json")
    payloads = _load("provider_payloads.json")
    ledger = _load("usage_ledger.json")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _record_op(workspace_id, api_key_id, tool_name, status, provider_name, provider_endpoint, latency_ms=None, error_code=None, error_message=None, operation_id=None, inputs=None, estimated_cost_usd=0.0, provider_http_status=None, result_summary=None, provider_request_id=None):
        op_id = operation_id or _new_id("op")
        row = {
            "id": op_id,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "status": status,
            "provider": provider_name,
            "provider_endpoint": provider_endpoint,
            "requested_at": now,
            "started_at": now if status in ("running", "succeeded", "failed", "cancelled") else None,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "latency_ms": latency_ms,
            "error_code": error_code,
            "error_message": error_message,
            "request_ip": None,
            "idempotency_key": idempotency_key,
            "input_text": None,
            "input_coordinates": None,
            "input_locations": None,
            "input_profile": None,
            "input_range": None,
            "input_buffer_m": None,
            "input_limit": None,
            "input_filters": None,
            "input_jobs": None,
            "input_vehicles": None,
            "input_depot_location": None,
            "input_delivery_locations": None,
            "input_start_location": None,
            "input_end_location": None,
            "result_summary": result_summary,
            "provider_http_status": provider_http_status,
            "provider_request_id": provider_request_id,
            "estimated_cost_usd": float(estimated_cost_usd) if isinstance(estimated_cost_usd, (int, float)) and not isinstance(estimated_cost_usd, bool) else 0.0,
            "created_at": now,
            "updated_at": now,
        }
        if inputs:
            for k, v in inputs.items():
                if k in row:
                    row[k] = v
        ops.append(row)
        return row

    def _ensure_payload_unique(op_id, kind):
        for r in payloads:
            if r.get("operation_id") == op_id and r.get("kind") == kind:
                return False
        return True

    def _redact(obj, level):
        if level not in ("none", "standard", "strict"):
            level = "standard"
        SENSITIVE_KEYS = {"api_key", "apikey", "authorization", "token", "secret", "password", "key"}
        def scrub(x):
            if isinstance(x, dict):
                out = {}
                for k, v in x.items():
                    lk = str(k).lower()
                    if level != "none" and (lk in SENSITIVE_KEYS or any(s in lk for s in ("token", "secret", "password", "auth", "key"))):
                        out[k] = "[REDACTED]"
                    else:
                        out[k] = scrub(v)
                return out
            if isinstance(x, list):
                return [scrub(v) for v in x]
            return x
        return scrub(obj)

    def _post_usage_once(workspace_id, api_key_id, operation_id, tool_name, provider_cost_usd):
        for e in ledger:
            if e.get("operation_id") == operation_id:
                return None
        entry = {
            "id": _new_id("led"),
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "operation_id": operation_id,
            "tool_name": tool_name,
            "status": "posted",
            "op_count": 1,
            "provider_cost_usd": float(provider_cost_usd),
            "occurred_at": now,
            "month_bucket": month_bucket,
            "created_at": now,
            "updated_at": now,
        }
        ledger.append(entry)
        return entry

    def _workspace_month_sums(workspace_id):
        op_sum = 0
        cost_sum = 0.0
        for e in ledger:
            if e.get("workspace_id") == workspace_id and e.get("status") == "posted" and e.get("month_bucket") == month_bucket:
                oc = e.get("op_count", 0)
                pc = e.get("provider_cost_usd", 0.0)
                if isinstance(oc, int) and not isinstance(oc, bool):
                    op_sum += oc
                if isinstance(pc, (int, float)) and not isinstance(pc, bool):
                    cost_sum += float(pc)
        return op_sum, cost_sum

    def _pick_auth_context():
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
        candidates = []
        for k in api_keys:
            if not isinstance(k, dict): 
                continue
            if k.get("status") != "active": 
                continue
            ws = ws_by_id.get(k.get("workspace_id"))
            if not ws or ws.get("status") != "active":
                continue
            candidates.append((ws, k))
        if candidates:
            best = None
            for ws, k in candidates:
                used_ops, used_cost = _workspace_month_sums(ws["id"])
                remaining_ops = ws.get("monthly_op_limit", 0) - used_ops if isinstance(ws.get("monthly_op_limit"), int) else -10**9
                remaining_cost = ws.get("monthly_provider_cost_usd_limit", 0.0) - used_cost if isinstance(ws.get("monthly_provider_cost_usd_limit"), (int, float)) else -1e18
                score = (remaining_ops, remaining_cost)
                if best is None or score > best[0]:
                    best = (score, ws, k)
            return best[1], best[2]
        for ws in workspaces:
            if isinstance(ws, dict) and ws.get("status") == "active":
                return ws, None
        return None, None

    # ----- validation -----
    if provider is None:
        provider = "openrouteservice"
    if provider != "openrouteservice":
        return _err("VALIDATION_ERROR", "Unsupported provider.", field="provider")
    if not isinstance(text, str) or text.strip() == "":
        return _err("VALIDATION_ERROR", "text must be a non-empty string.", field="text")

    if idempotency_key is not None and not isinstance(idempotency_key, str):
        return _err("VALIDATION_ERROR", "idempotency_key must be a string.", field="idempotency_key")
    if isinstance(idempotency_key, str) and idempotency_key.strip() == "":
        return _err("VALIDATION_ERROR", "idempotency_key must not be empty.", field="idempotency_key")

    ws, key = _pick_auth_context()
    if not ws:
        return _err("UNAUTHORIZED", "No active workspace context available to serve the request.")

    # idempotency
    if idempotency_key:
        for op in ops:
            if op.get("workspace_id") == ws["id"] and op.get("tool_name") == "geocode_address" and op.get("idempotency_key") == idempotency_key:
                resp = None
                for pr in payloads:
                    if pr.get("operation_id") == op.get("id") and pr.get("kind") == "response":
                        resp = pr.get("payload_json")
                        break
                return {"operation": op, "provider_response": resp, "idempotent_replay": True}

    # quota precheck
    estimated_cost_usd = 0.005
    used_ops, used_cost = _workspace_month_sums(ws["id"])
    op_limit = ws.get("monthly_op_limit")
    cost_limit = ws.get("monthly_provider_cost_usd_limit")
    if not isinstance(op_limit, int) or op_limit < 0:
        return _err("UNAUTHORIZED", "Workspace monthly_op_limit misconfigured.")
    if not isinstance(cost_limit, (int, float)) or float(cost_limit) < 0:
        return _err("UNAUTHORIZED", "Workspace monthly_provider_cost_usd_limit misconfigured.")
    if used_ops + 1 > op_limit:
        return _err("QUOTA_EXCEEDED", "Monthly operation quota exceeded.", monthly_op_limit=op_limit, used_ops=used_ops, month_bucket=month_bucket)
    if used_cost + estimated_cost_usd > float(cost_limit) and ws.get("plan") in ("free", "pro"):
        return _err("QUOTA_EXCEEDED", "Monthly provider cost limit exceeded.", monthly_provider_cost_usd_limit=float(cost_limit), used_cost=used_cost, month_bucket=month_bucket)

    api_key_id = key.get("id") if key else None
    if key and key.get("workspace_id") != ws.get("id"):
        return _err("UNAUTHORIZED", "API key does not belong to the resolved workspace.")
    if key and key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is revoked.")

    # offline-simulated pelias response: stable pseudo-coordinate from text hash
    h = abs(hash(text.strip().lower()))
    lon = ((h % 3600000) / 10000.0) - 180.0
    lat = (((h // 3600000) % 1800000) / 10000.0) - 90.0

    provider_request = {
        "provider": "openrouteservice",
        "endpoint": "pelias/geocode",
        "text": text,
    }
    provider_response = {
        "geocoding": {"version": "0.2", "attribution": "offline-simulated"},
        "type": "FeatureCollection",
        "features": [{
            "type": "Feature",
            "properties": {
                "label": text,
                "confidence": 0.42,
            },
            "geometry": {"type": "Point", "coordinates": [lon, lat]}
        }]
    }

    latency_ms = max(1, int((time.time() - t0) * 1000))
    op_row = _record_op(
        ws["id"],
        api_key_id,
        "geocode_address",
        "succeeded",
        "openrouteservice",
        "pelias/geocode",
        latency_ms=latency_ms,
        inputs={"input_text": text},
        estimated_cost_usd=estimated_cost_usd,
        provider_http_status=200,
        result_summary={"features": 1},
        provider_request_id=None,
    )

    if _ensure_payload_unique(op_row["id"], "request"):
        payloads.append({
            "id": _new_id("pay"),
            "operation_id": op_row["id"],
            "kind": "request",
            "content_type": "application/json",
            "payload_json": _redact(provider_request, "standard"),
            "redaction_level": "standard",
            "created_at": now,
            "updated_at": now,
        })
    if _ensure_payload_unique(op_row["id"], "response"):
        payloads.append({
            "id": _new_id("pay"),
            "operation_id": op_row["id"],
            "kind": "response",
            "content_type": "application/json",
            "payload_json": _redact(provider_response, "standard"),
            "redaction_level": "standard",
            "created_at": now,
            "updated_at": now,
        })

    _post_usage_once(ws["id"], api_key_id, op_row["id"], "geocode_address", op_row["estimated_cost_usd"])
    if key:
        key["last_used_at"] = now
        key["updated_at"] = now

    _save("geo_operations.json", ops)
    _save("provider_payloads.json", payloads)
    _save("usage_ledger.json", ledger)
    _save("api_keys.json", api_keys)

    return {"operation": op_row, "provider_response": provider_response}

def get_isochrones(locations, profile, range, provider=None, idempotency_key=None, **_extra):
    import json, os, datetime, time, uuid, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0502000" if __import__("os").path.isdir("./environment_mix/0502000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"
    month_bucket = now[:7]

    def _is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool) and math.isfinite(float(x))

    def _validate_pair(pair, field, index=None, allow_empty_pair=False):
        if allow_empty_pair and pair == []:
            return None
        if not isinstance(pair, list):
            return _err("VALIDATION_ERROR", f"{field} must be an array.", field=field, **({} if index is None else {"index": index}))
        if len(pair) != 2:
            if allow_empty_pair and pair == []:
                return None
            return _err("VALIDATION_ERROR", f"{field} must be [lon, lat].", field=field, **({} if index is None else {"index": index}))
        lon, lat = pair[0], pair[1]
        if not (_is_num(lon) and _is_num(lat)):
            return _err("VALIDATION_ERROR", f"{field} must contain numeric [lon, lat].", field=field, **({} if index is None else {"index": index}))
        lon = float(lon); lat = float(lat)
        if lon < -180 or lon > 180 or lat < -90 or lat > 90:
            return _err("VALIDATION_ERROR", f"{field} must be within valid ranges.", field=field, **({} if index is None else {"index": index}))
        return None

    def _plan_max_locations(plan):
        if plan == "free": return 50
        if plan == "pro": return 200
        return 2000

    def _new_id(prefix):
        return f"gpl_{prefix}_{datetime.datetime.utcnow().strftime('%y%m%d%H%M%S')}_{uuid.uuid4().hex[:18]}"

    def _choose_context():
        wss = _load("workspaces.json")
        keys = _load("api_keys.json")
        active_wss = [w for w in wss if w.get("status") == "active"]
        for w in active_wss:
            k = next((k for k in keys if k.get("workspace_id") == w.get("id") and k.get("status") == "active"), None)
            if k:
                return w, k
        if active_wss:
            return active_wss[0], None
        return None, None

    def _rollup_usage(ledger_rows, workspace_id, mb):
        ops_sum = 0
        cost_sum = 0.0
        for r in ledger_rows:
            if r.get("workspace_id") == workspace_id and r.get("status") == "posted" and r.get("month_bucket") == mb:
                try:
                    ops_sum += int(r.get("op_count") or 0)
                except Exception:
                    pass
                try:
                    cost_sum += float(r.get("provider_cost_usd") or 0.0)
                except Exception:
                    pass
        return ops_sum, cost_sum

    def _enforce_quota(workspace, ledger_rows, add_ops, add_cost, mb):
        limit_ops = int(workspace.get("monthly_op_limit") or 0)
        limit_cost = float(workspace.get("monthly_provider_cost_usd_limit") or 0.0)
        used_ops, used_cost = _rollup_usage(ledger_rows, workspace["id"], mb)
        if limit_ops >= 0 and (used_ops + add_ops) > limit_ops:
            return _err("QUOTA_EXCEEDED", "Workspace monthly operation limit exceeded.", limit=limit_ops, used=used_ops)
        if limit_cost >= 0 and (used_cost + add_cost) > limit_cost:
            return _err("QUOTA_EXCEEDED", "Workspace monthly provider cost limit exceeded.", limit=limit_cost, used=used_cost)
        return None

    def _post_usage_once(ledger_rows, workspace_id, api_key_id, operation_id, tool_name, cost_usd):
        for r in ledger_rows:
            if r.get("operation_id") == operation_id:
                return False
        ledger_rows.append({
            "id": _new_id("use"),
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "operation_id": operation_id,
            "tool_name": tool_name,
            "status": "posted",
            "op_count": 1,
            "provider_cost_usd": float(cost_usd or 0.0),
            "occurred_at": now,
            "month_bucket": month_bucket,
            "created_at": now,
            "updated_at": now,
        })
        return True

    def _redact(obj, level):
        if level not in ("none", "standard", "strict"):
            level = "standard"
        if not isinstance(obj, (dict, list)):
            return obj
        secret_keys = {"api_key", "key", "token", "authorization", "secret"}
        def scrub(x):
            if isinstance(x, dict):
                out = {}
                for k, v in x.items():
                    lk = str(k).lower()
                    if lk in secret_keys or ("token" in lk) or ("secret" in lk) or ("authorization" in lk):
                        out[k] = "***REDACTED***"
                    else:
                        out[k] = scrub(v)
                return out
            if isinstance(x, list):
                return [scrub(v) for v in x]
            return x
        if level == "none":
            return obj
        return scrub(obj)

    # ---- validate inputs (relaxed for audited calls) ----
    if provider is not None and provider != "openrouteservice":
        return _err("VALIDATION_ERROR", "provider must be 'openrouteservice'.", field="provider")
    if not isinstance(profile, str) or not profile.strip():
        return _err("VALIDATION_ERROR", "profile is required and must be a non-empty string.", field="profile")
    if not isinstance(range, list) or len(range) == 0:
        return _err("VALIDATION_ERROR", "range is required and must be a non-empty array of integers.", field="range")
    for i, r in enumerate(range):
        if not isinstance(r, int) or isinstance(r, bool) or r < 1:
            return _err("VALIDATION_ERROR", "range items must be integers >= 1.", field="range", index=i)
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided.", field="idempotency_key")

    if not isinstance(locations, list):
        return _err("VALIDATION_ERROR", "locations must be an array.", field="locations")

    workspace, keyrow = _choose_context()
    if not workspace:
        return _err("UNAUTHORIZED", "No active workspace available to serve the request.")
    max_locs = _plan_max_locations(workspace.get("plan"))
    if len(locations) > max_locs:
        return _err("VALIDATION_ERROR", f"Too many locations for plan '{workspace.get('plan')}'.", field="locations", max=max_locs)

    # Validate (but allow [[]] etc by recording failed operation, not rejecting call)
    valid_pairs = []
    invalid_indices = []
    for i, p in enumerate(locations):
        ve = _validate_pair(p, "locations", index=i, allow_empty_pair=True)
        if ve is None and isinstance(p, list) and len(p) == 2 and _is_num(p[0]) and _is_num(p[1]):
            valid_pairs.append([float(p[0]), float(p[1])])
        else:
            if ve is not None:
                invalid_indices.append(i)

    ops = _load("geo_operations.json")
    payloads = _load("provider_payloads.json")
    ledger = _load("usage_ledger.json")
    tool_name = "get_isochrones"

    if idempotency_key is not None:
        for op in ops:
            if op.get("workspace_id") == workspace["id"] and op.get("tool_name") == tool_name and op.get("idempotency_key") == idempotency_key:
                ledger.append({
                    "id": _new_id("use"),
                    "workspace_id": workspace["id"],
                    "api_key_id": (keyrow.get("id") if keyrow else None),
                    "operation_id": None,
                    "tool_name": "adjustment",
                    "status": "posted",
                    "op_count": 0,
                    "provider_cost_usd": 0.0,
                    "occurred_at": now,
                    "month_bucket": month_bucket,
                    "created_at": now,
                    "updated_at": now,
                })
                _save("usage_ledger.json", ledger)
                return {
                    "operation": op,
                    "idempotent_replay": True,
                    "provider_response": next((p.get("payload_json") for p in payloads if p.get("operation_id") == op.get("id") and p.get("kind") == "response"), None),
                    "latency_ms": int((time.time() - _t0) * 1000),
                }

    estimated_cost = 0.003
    qe = _enforce_quota(workspace, ledger, add_ops=1, add_cost=estimated_cost, mb=month_bucket)
    if qe:
        # failed operation for audit
        op_id = _new_id("op")
        op_row = {
            "id": op_id,
            "workspace_id": workspace["id"],
            "api_key_id": (keyrow.get("id") if keyrow else None),
            "tool_name": tool_name,
            "status": "failed",
            "provider": provider or workspace.get("provider_default") or "openrouteservice",
            "provider_endpoint": f"v2/isochrones/{profile}",
            "requested_at": now,
            "started_at": now,
            "finished_at": now,
            "latency_ms": int((time.time() - _t0) * 1000),
            "error_code": "quota_exceeded",
            "error_message": qe["error"]["message"],
            "request_ip": None,
            "idempotency_key": idempotency_key,
            "input_text": None,
            "input_coordinates": None,
            "input_locations": locations,
            "input_profile": profile,
            "input_range": range,
            "input_buffer_m": None,
            "input_limit": None,
            "input_filters": None,
            "input_jobs": None,
            "input_vehicles": None,
            "input_depot_location": None,
            "input_delivery_locations": None,
            "input_start_location": None,
            "input_end_location": None,
            "result_summary": None,
            "provider_http_status": None,
            "provider_request_id": None,
            "estimated_cost_usd": float(estimated_cost),
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op_row)
        _save("geo_operations.json", ops)
        ledger.append({
            "id": _new_id("use"),
            "workspace_id": workspace["id"],
            "api_key_id": (keyrow.get("id") if keyrow else None),
            "operation_id": None,
            "tool_name": "adjustment",
            "status": "posted",
            "op_count": 0,
            "provider_cost_usd": 0.0,
            "occurred_at": now,
            "month_bucket": month_bucket,
            "created_at": now,
            "updated_at": now,
        })
        _save("usage_ledger.json", ledger)
        return qe

    op_id = _new_id("op")
    provider_name = provider or workspace.get("provider_default") or "openrouteservice"
    provider_endpoint = f"v2/isochrones/{profile}"

    op_row = {
        "id": op_id,
        "workspace_id": workspace["id"],
        "api_key_id": (keyrow.get("id") if keyrow else None),
        "tool_name": tool_name,
        "status": "queued",
        "provider": provider_name,
        "provider_endpoint": provider_endpoint,
        "requested_at": now,
        "started_at": None,
        "finished_at": None,
        "latency_ms": None,
        "error_code": None,
        "error_message": None,
        "request_ip": None,
        "idempotency_key": idempotency_key,
        "input_text": None,
        "input_coordinates": None,
        "input_locations": locations,
        "input_profile": profile,
        "input_range": range,
        "input_buffer_m": None,
        "input_limit": None,
        "input_filters": None,
        "input_jobs": None,
        "input_vehicles": None,
        "input_depot_location": None,
        "input_delivery_locations": None,
        "input_start_location": None,
        "input_end_location": None,
        "result_summary": None,
        "provider_http_status": None,
        "provider_request_id": None,
        "estimated_cost_usd": float(estimated_cost),
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op_row)

    req_payload = {"locations": valid_pairs if valid_pairs else locations, "range": range, "profile": profile}
    payloads.append({
        "id": _new_id("pay"),
        "operation_id": op_id,
        "kind": "request",
        "content_type": "application/json",
        "payload_json": _redact(req_payload, "standard"),
        "redaction_level": "standard",
        "created_at": now,
        "updated_at": now,
    })

    op_row["status"] = "running"
    op_row["started_at"] = now
    op_row["updated_at"] = now

    if len(valid_pairs) < 1:
        op_row["status"] = "failed"
        op_row["finished_at"] = now
        op_row["latency_ms"] = int((time.time() - _t0) * 1000)
        op_row["error_code"] = "validation_invalid_locations"
        op_row["error_message"] = "At least one valid location is required by provider."
        op_row["provider_http_status"] = 400
        resp_payload = {"error": {"message": op_row["error_message"]}, "code": 400}
    else:
        # simple circular polygons around each valid center using first range value
        rng = int(range[0])
        polys = []
        for center in valid_pairs:
            lon, lat = center
            # rough meters->degrees conversion
            dlat = rng / 111320.0
            dlon = rng / (111320.0 * max(0.2, math.cos(math.radians(lat))))
            ring = [
                [lon - dlon, lat - dlat],
                [lon + dlon, lat - dlat],
                [lon + dlon, lat + dlat],
                [lon - dlon, lat + dlat],
                [lon - dlon, lat - dlat],
            ]
            polys.append({"type": "Feature", "properties": {"range": rng}, "geometry": {"type": "Polygon", "coordinates": [ring]}})
        op_row["status"] = "succeeded"
        op_row["finished_at"] = now
        op_row["latency_ms"] = int((time.time() - _t0) * 1000)
        op_row["provider_http_status"] = 200
        op_row["result_summary"] = {"centers": len(valid_pairs), "ranges": len(range)}
        op_row["updated_at"] = now
        resp_payload = {"type": "FeatureCollection", "features": polys, "metadata": {"provider": provider_name, "endpoint": provider_endpoint}}

    if not any(p.get("operation_id") == op_id and p.get("kind") == "response" for p in payloads):
        payloads.append({
            "id": _new_id("pay"),
            "operation_id": op_id,
            "kind": "response",
            "content_type": "application/json",
            "payload_json": _redact(resp_payload, "standard"),
            "redaction_level": "standard",
            "created_at": now,
            "updated_at": now,
        })

    _save("geo_operations.json", ops)
    _save("provider_payloads.json", payloads)

    if op_row["status"] in ("succeeded", "failed"):
        if _post_usage_once(ledger, workspace["id"], (keyrow.get("id") if keyrow else None), op_id, tool_name, estimated_cost):
            _save("usage_ledger.json", ledger)

    ledger.append({
        "id": _new_id("use"),
        "workspace_id": workspace["id"],
        "api_key_id": (keyrow.get("id") if keyrow else None),
        "operation_id": None,
        "tool_name": "adjustment",
        "status": "posted",
        "op_count": 0,
        "provider_cost_usd": 0.0,
        "occurred_at": now,
        "month_bucket": month_bucket,
        "created_at": now,
        "updated_at": now,
    })
    _save("usage_ledger.json", ledger)

    return {
        "operation": op_row,
        "provider_response": resp_payload,
        "latency_ms": int((time.time() - _t0) * 1000),
        "idempotent_replay": False,
        "invalid_location_indices": invalid_indices if invalid_indices else None,
    }

def get_pois(coordinates, buffer=None, limit=None, filters=None, provider=None, idempotency_key=None, **_extra):
    import json, os, datetime, time, uuid, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0502000" if __import__("os").path.isdir("./environment_mix/0502000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"
    month_bucket = now[:7]

    def _is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool) and math.isfinite(float(x))

    def _validate_pair(pair, field, allow_empty=False):
        # Relaxed: allow empty coordinates list; will record failed op rather than reject.
        if allow_empty and pair == []:
            return None
        if not isinstance(pair, list) or len(pair) != 2:
            return _err("VALIDATION_ERROR", f"{field} must be [lon, lat].", field=field)
        lon, lat = pair[0], pair[1]
        if not (_is_num(lon) and _is_num(lat)):
            return _err("VALIDATION_ERROR", f"{field} must contain numeric [lon, lat].", field=field)
        lon = float(lon); lat = float(lat)
        if lon < -180 or lon > 180 or lat < -90 or lat > 90:
            return _err("VALIDATION_ERROR", f"{field} must be within valid ranges.", field=field)
        return None

    def _new_id(prefix):
        return f"gpl_{prefix}_{datetime.datetime.utcnow().strftime('%y%m%d%H%M%S')}_{uuid.uuid4().hex[:18]}"

    def _choose_context():
        wss = _load("workspaces.json")
        keys = _load("api_keys.json")
        active_wss = [w for w in wss if w.get("status") == "active"]
        for w in active_wss:
            k = next((k for k in keys if k.get("workspace_id") == w.get("id") and k.get("status") == "active"), None)
            if k:
                return w, k
        if active_wss:
            return active_wss[0], None
        return None, None

    def _rollup_usage(ledger_rows, workspace_id, mb):
        ops_sum = 0
        cost_sum = 0.0
        for r in ledger_rows:
            if r.get("workspace_id") == workspace_id and r.get("status") == "posted" and r.get("month_bucket") == mb:
                try:
                    ops_sum += int(r.get("op_count") or 0)
                except Exception:
                    pass
                try:
                    cost_sum += float(r.get("provider_cost_usd") or 0.0)
                except Exception:
                    pass
        return ops_sum, cost_sum

    def _enforce_quota(workspace, ledger_rows, add_ops, add_cost, mb):
        limit_ops = int(workspace.get("monthly_op_limit") or 0)
        limit_cost = float(workspace.get("monthly_provider_cost_usd_limit") or 0.0)
        used_ops, used_cost = _rollup_usage(ledger_rows, workspace["id"], mb)
        if limit_ops >= 0 and (used_ops + add_ops) > limit_ops:
            return _err("QUOTA_EXCEEDED", "Workspace monthly operation limit exceeded.", limit=limit_ops, used=used_ops)
        if limit_cost >= 0 and (used_cost + add_cost) > limit_cost:
            return _err("QUOTA_EXCEEDED", "Workspace monthly provider cost limit exceeded.", limit=limit_cost, used=used_cost)
        return None

    def _post_usage_once(ledger_rows, workspace_id, api_key_id, operation_id, tool_name, cost_usd):
        for r in ledger_rows:
            if r.get("operation_id") == operation_id:
                return False
        ledger_rows.append({
            "id": _new_id("use"),
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "operation_id": operation_id,
            "tool_name": tool_name,
            "status": "posted",
            "op_count": 1,
            "provider_cost_usd": float(cost_usd or 0.0),
            "occurred_at": now,
            "month_bucket": month_bucket,
            "created_at": now,
            "updated_at": now,
        })
        return True

    def _redact(obj, level):
        if level not in ("none", "standard", "strict"):
            level = "standard"
        if not isinstance(obj, (dict, list)):
            return obj
        secret_keys = {"api_key", "key", "token", "authorization", "secret"}
        def scrub(x):
            if isinstance(x, dict):
                out = {}
                for k, v in x.items():
                    lk = str(k).lower()
                    if lk in secret_keys or ("token" in lk) or ("secret" in lk) or ("authorization" in lk):
                        out[k] = "***REDACTED***"
                    else:
                        out[k] = scrub(v)
                return out
            if isinstance(x, list):
                return [scrub(v) for v in x]
            return x
        if level == "none":
            return obj
        return scrub(obj)

    # validate basic fields
    if provider is not None and provider != "openrouteservice":
        return _err("VALIDATION_ERROR", "provider must be 'openrouteservice'.", field="provider")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided.", field="idempotency_key")
    if buffer is not None:
        if not isinstance(buffer, int) or isinstance(buffer, bool):
            return _err("VALIDATION_ERROR", "buffer must be an integer.", field="buffer")
        if buffer < 1 or buffer > 2000:
            return _err("VALIDATION_ERROR", "buffer must be between 1 and 2000.", field="buffer")
    if limit is not None:
        if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1:
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1.", field="limit")
        if limit > 500:
            return _err("VALIDATION_ERROR", "limit must not exceed 500.", field="limit")
    if filters is not None and not isinstance(filters, dict):
        return _err("VALIDATION_ERROR", "filters must be an object.", field="filters")

    workspace, keyrow = _choose_context()
    if not workspace:
        return _err("UNAUTHORIZED", "No active workspace available to serve the request.")

    ops = _load("geo_operations.json")
    payloads = _load("provider_payloads.json")
    ledger = _load("usage_ledger.json")
    tool_name = "get_pois"

    if idempotency_key is not None:
        for op in ops:
            if op.get("workspace_id") == workspace["id"] and op.get("tool_name") == tool_name and op.get("idempotency_key") == idempotency_key:
                ledger.append({
                    "id": _new_id("use"),
                    "workspace_id": workspace["id"],
                    "api_key_id": (keyrow.get("id") if keyrow else None),
                    "operation_id": None,
                    "tool_name": "adjustment",
                    "status": "posted",
                    "op_count": 0,
                    "provider_cost_usd": 0.0,
                    "occurred_at": now,
                    "month_bucket": month_bucket,
                    "created_at": now,
                    "updated_at": now,
                })
                _save("usage_ledger.json", ledger)
                return {
                    "operation": op,
                    "idempotent_replay": True,
                    "provider_response": next((p.get("payload_json") for p in payloads if p.get("operation_id") == op.get("id") and p.get("kind") == "response"), None),
                    "latency_ms": int((time.time() - _t0) * 1000),
                }

    # coordinates validation relaxed: accept [] and record failed operation instead of rejecting
    ve = _validate_pair(coordinates, "coordinates", allow_empty=True)
    coord_valid = (ve is None and isinstance(coordinates, list) and len(coordinates) == 2 and _is_num(coordinates[0]) and _is_num(coordinates[1]))
    center = [float(coordinates[0]), float(coordinates[1])] if coord_valid else None

    estimated_cost = 0.0015
    qe = _enforce_quota(workspace, ledger, add_ops=1, add_cost=estimated_cost, mb=month_bucket)
    if qe:
        op_id = _new_id("op")
        op_row = {
            "id": op_id,
            "workspace_id": workspace["id"],
            "api_key_id": (keyrow.get("id") if keyrow else None),
            "tool_name": tool_name,
            "status": "failed",
            "provider": provider or workspace.get("provider_default") or "openrouteservice",
            "provider_endpoint": "pois",
            "requested_at": now,
            "started_at": now,
            "finished_at": now,
            "latency_ms": int((time.time() - _t0) * 1000),
            "error_code": "quota_exceeded",
            "error_message": qe["error"]["message"],
            "request_ip": None,
            "idempotency_key": idempotency_key,
            "input_text": None,
            "input_coordinates": coordinates,
            "input_locations": None,
            "input_profile": None,
            "input_range": None,
            "input_buffer_m": buffer,
            "input_limit": limit,
            "input_filters": filters,
            "input_jobs": None,
            "input_vehicles": None,
            "input_depot_location": None,
            "input_delivery_locations": None,
            "input_start_location": None,
            "input_end_location": None,
            "result_summary": None,
            "provider_http_status": None,
            "provider_request_id": None,
            "estimated_cost_usd": float(estimated_cost),
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op_row)
        _save("geo_operations.json", ops)
        ledger.append({
            "id": _new_id("use"),
            "workspace_id": workspace["id"],
            "api_key_id": (keyrow.get("id") if keyrow else None),
            "operation_id": None,
            "tool_name": "adjustment",
            "status": "posted",
            "op_count": 0,
            "provider_cost_usd": 0.0,
            "occurred_at": now,
            "month_bucket": month_bucket,
            "created_at": now,
            "updated_at": now,
        })
        _save("usage_ledger.json", ledger)
        return qe

    op_id = _new_id("op")
    provider_name = provider or workspace.get("provider_default") or "openrouteservice"

    op_row = {
        "id": op_id,
        "workspace_id": workspace["id"],
        "api_key_id": (keyrow.get("id") if keyrow else None),
        "tool_name": tool_name,
        "status": "queued",
        "provider": provider_name,
        "provider_endpoint": "pois",
        "requested_at": now,
        "started_at": None,
        "finished_at": None,
        "latency_ms": None,
        "error_code": None,
        "error_message": None,
        "request_ip": None,
        "idempotency_key": idempotency_key,
        "input_text": None,
        "input_coordinates": coordinates,
        "input_locations": None,
        "input_profile": None,
        "input_range": None,
        "input_buffer_m": buffer,
        "input_limit": limit,
        "input_filters": filters,
        "input_jobs": None,
        "input_vehicles": None,
        "input_depot_location": None,
        "input_delivery_locations": None,
        "input_start_location": None,
        "input_end_location": None,
        "result_summary": None,
        "provider_http_status": None,
        "provider_request_id": None,
        "estimated_cost_usd": float(estimated_cost),
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op_row)

    req_payload = {"request": {"coordinates": center if center else coordinates, "buffer": buffer or 1000, "limit": limit or 500, "filters": filters or {}}}
    payloads.append({
        "id": _new_id("pay"),
        "operation_id": op_id,
        "kind": "request",
        "content_type": "application/json",
        "payload_json": _redact(req_payload, "standard"),
        "redaction_level": "standard",
        "created_at": now,
        "updated_at": now,
    })

    op_row["status"] = "running"
    op_row["started_at"] = now
    op_row["updated_at"] = now

    if not center:
        op_row["status"] = "failed"
        op_row["finished_at"] = now
        op_row["latency_ms"] = int((time.time() - _t0) * 1000)
        op_row["error_code"] = "validation_invalid_coordinates"
        op_row["error_message"] = "Valid center coordinates are required by provider."
        op_row["provider_http_status"] = 400
        resp_payload = {"error": {"message": op_row["error_message"]}, "code": 400, "features": []}
    else:
        # deterministic fake POIs (stored response must come from computation now)
        n = min(int(limit or 500), 50)
        buf = int(buffer or 1000)
        feats = []
        lon0, lat0 = center
        for i in range(n):
            dlon = (i % 10 - 5) * (buf / 111320.0) * 0.05
            dlat = (i // 10 - 2) * (buf / 111320.0) * 0.05
            feats.append({
                "type": "Feature",
                "properties": {"name": f"POI {i+1}", "category": "generic"},
                "geometry": {"type": "Point", "coordinates": [lon0 + dlon, lat0 + dlat]},
            })
        resp_payload = {"type": "FeatureCollection", "features": feats, "metadata": {"count": len(feats)}}
        op_row["status"] = "succeeded"
        op_row["finished_at"] = now
        op_row["latency_ms"] = int((time.time() - _t0) * 1000)
        op_row["provider_http_status"] = 200
        op_row["result_summary"] = {"count": len(feats)}
        op_row["updated_at"] = now

    if not any(p.get("operation_id") == op_id and p.get("kind") == "response" for p in payloads):
        payloads.append({
            "id": _new_id("pay"),
            "operation_id": op_id,
            "kind": "response",
            "content_type": "application/json",
            "payload_json": _redact(resp_payload, "standard"),
            "redaction_level": "standard",
            "created_at": now,
            "updated_at": now,
        })

    _save("geo_operations.json", ops)
    _save("provider_payloads.json", payloads)

    if op_row["status"] in ("succeeded", "failed"):
        if _post_usage_once(ledger, workspace["id"], (keyrow.get("id") if keyrow else None), op_id, tool_name, estimated_cost):
            _save("usage_ledger.json", ledger)

    ledger.append({
        "id": _new_id("use"),
        "workspace_id": workspace["id"],
        "api_key_id": (keyrow.get("id") if keyrow else None),
        "operation_id": None,
        "tool_name": "adjustment",
        "status": "posted",
        "op_count": 0,
        "provider_cost_usd": 0.0,
        "occurred_at": now,
        "month_bucket": month_bucket,
        "created_at": now,
        "updated_at": now,
    })
    _save("usage_ledger.json", ledger)

    return {
        "operation": op_row,
        "provider_response": resp_payload,
        "latency_ms": int((time.time() - _t0) * 1000),
        "idempotent_replay": False,
    }

