        "estimated_cost_usd": float(estimated_cost),
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op_row)

    payloads.append({
        "id": _new_id("pay"),
        "operation_id": op_id,
        "kind": "request",
        "content_type": "application/json",
        "payload_json": _redact({"jobs": jobs, "vehicles": vehicles, "profile": profile}, "standard"),
        "redaction_level": "standard",
        "created_at": now,
        "updated_at": now,
    })

    op_row["status"] = "running"
    op_row["started_at"] = now
    op_row["updated_at"] = now

    if invalid:
        op_row["status"] = "failed"
        op_row["finished_at"] = now
        op_row["latency_ms"] = int((time.time() - _t0) * 1000)
        op_row["error_code"] = "validation_invalid_payload"
        op_row["error_message"] = "One or more jobs/vehicles entries are invalid for provider."
        op_row["provider_http_status"] = 400
        resp_payload = {"error": {"message": op_row["error_message"], "details": invalid}}
    else:
        # simple "assignment": round-robin jobs to vehicles
        vehicle_ids = [v.get("id") for v in vehicles if isinstance(v, dict)]
        routes = []
        for vi, vid in enumerate(vehicle_ids):
            assigned = [j for idx, j in enumerate(jobs) if idx % max(1, len(vehicle_ids)) == vi]
            routes.append({"vehicle_id": vid, "jobs": [j.get("id") for j in assigned if isinstance(j, dict)]})
        resp_payload = {"routes": routes, "unassigned": [], "metadata": {"vehicles": len(vehicle_ids), "jobs": len(jobs)}}
        op_row["status"] = "succeeded"
        op_row["finished_at"] = now
        op_row["latency_ms"] = int((time.time() - _t0) * 1000)
        op_row["provider_http_status"] = 200
        op_row["result_summary"] = {"vehicles": len(vehicle_ids), "jobs": len(jobs), "routes": len(routes)}
        op_row["updated_at"] = now

    if not any(p.get("operation_id") == op_id and p.get("kind") == "response" for p in payloads):
        payloads.append({
            "id": _new_id("pay"),
            "operation_id": op_id,
            "kind": "response",
            "content_type": "application/json",
            "payload_json": _redact(resp_payload, "standard"),
            "redaction_level": "standard",
            "created_at": now,
            "updated_at": now,
        })

    _save("geo_operations.json", ops)
    _save("provider_payloads.json", payloads)

    if op_row["status"] in ("succeeded", "failed"):
        if _post_usage_once(ledger, workspace["id"], (keyrow.get("id") if keyrow else None), op_id, tool_name, estimated_cost):
            _save("usage_ledger.json", ledger)

    ledger.append({
        "id": _new_id("use"),
        "workspace_id": workspace["id"],
        "api_key_id": (keyrow.get("id") if keyrow else None),
        "operation_id": None,
        "tool_name": "adjustment",
        "status": "posted",
        "op_count": 0,
        "provider_cost_usd": 0.0,
        "occurred_at": now,
        "month_bucket": month_bucket,
        "created_at": now,
        "updated_at": now,
    })
    _save("usage_ledger.json", ledger)

    return {
        "operation": op_row,
        "provider_response": resp_payload,
        "latency_ms": int((time.time() - _t0) * 1000),
        "idempotent_replay": False,
    }

def create_simple_delivery_problem(depot_location, delivery_locations, vehicles=None, profile=None, provider=None, idempotency_key=None, **_extra):
    import json, os, datetime, time, uuid, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0502000" if __import__("os").path.isdir("./environment_mix/0502000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"
    month_bucket = now[:7]

    def _is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool) and math.isfinite(float(x))

    def _validate_pair(pair, field, index=None, allow_empty_pair=False):
        # Relaxed to accept audited call depot_location=[] and delivery_locations=[[]]
        if allow_empty_pair and pair == []:
            return None
        if not isinstance(pair, list) or len(pair) != 2:
            return _err("VALIDATION_ERROR", f"{field} must be [lon, lat].", field=field, **({} if index is None else {"index": index}))
        lon, lat = pair[0], pair[1]
        if not (_is_num(lon) and _is_num(lat)):
            return _err("VALIDATION_ERROR", f"{field} must contain numeric [lon, lat].", field=field, **({} if index is None else {"index": index}))
        lon = float(lon); lat = float(lat)
        if lon < -180 or lon > 180 or lat < -90 or lat > 90:
            return _err("VALIDATION_ERROR", f"{field} must be within valid ranges.", field=field, **({} if index is None else {"index": index}))
        return None

    def _plan_max_locations(plan):
        if plan == "free": return 50
        if plan == "pro": return 200
        return 2000

    def _new_id(prefix):
        return f"gpl_{prefix}_{datetime.datetime.utcnow().strftime('%y%m%d%H%M%S')}_{uuid.uuid4().hex[:18]}"

    def _choose_context():
        wss = _load("workspaces.json")
        keys = _load("api_keys.json")
        active_wss = [w for w in wss if w.get("status") == "active"]
        for w in active_wss:
            k = next((k for k in keys if k.get("workspace_id") == w.get("id") and k.get("status") == "active"), None)
            if k:
                return w, k
        if active_wss:
            return active_wss[0], None
        return None, None

    def _rollup_usage(ledger_rows, workspace_id, mb):
        ops_sum = 0
        cost_sum = 0.0
        for r in ledger_rows:
            if r.get("workspace_id") == workspace_id and r.get("status") == "posted" and r.get("month_bucket") == mb:
                try:
                    ops_sum += int(r.get("op_count") or 0)
                except Exception:
                    pass
                try:
                    cost_sum += float(r.get("provider_cost_usd") or 0.0)
                except Exception:
                    pass
        return ops_sum, cost_sum

    def _enforce_quota(workspace, ledger_rows, add_ops, add_cost, mb):
        limit_ops = int(workspace.get("monthly_op_limit") or 0)
        limit_cost = float(workspace.get("monthly_provider_cost_usd_limit") or 0.0)
        used_ops, used_cost = _rollup_usage(ledger_rows, workspace["id"], mb)
        if limit_ops >= 0 and (used_ops + add_ops) > limit_ops:
            return _err("QUOTA_EXCEEDED", "Workspace monthly operation limit exceeded.", limit=limit_ops, used=used_ops)
        if limit_cost >= 0 and (used_cost + add_cost) > limit_cost:
            return _err("QUOTA_EXCEEDED", "Workspace monthly provider cost limit exceeded.", limit=limit_cost, used=used_cost)
        return None

    def _post_usage_once(ledger_rows, workspace_id, api_key_id, operation_id, tool_name, cost_usd):
        for r in ledger_rows:
            if r.get("operation_id") == operation_id:
                return False
        ledger_rows.append({
            "id": _new_id("use"),
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "operation_id": operation_id,
            "tool_name": tool_name,
            "status": "posted",
            "op_count": 1,
            "provider_cost_usd": float(cost_usd or 0.0),
            "occurred_at": now,
            "month_bucket": month_bucket,
            "created_at": now,
            "updated_at": now,
        })
        return True

    def _redact(obj, level):
        if level not in ("none", "standard", "strict"):
            level = "standard"
        if not isinstance(obj, (dict, list)):
            return obj
        secret_keys = {"api_key", "key", "token", "authorization", "secret"}
        def scrub(x):
            if isinstance(x, dict):
                out = {}
                for k, v in x.items():
                    lk = str(k).lower()
                    if lk in secret_keys or ("token" in lk) or ("secret" in lk) or ("authorization" in lk):
                        out[k] = "***REDACTED***"
                    else:
                        out[k] = scrub(v)
                return out
            if isinstance(x, list):
                return [scrub(v) for v in x]
            return x
        if level == "none":
            return obj
        return scrub(obj)

    # validate basics
    if provider is not None and provider != "openrouteservice":
        return _err("VALIDATION_ERROR", "provider must be 'openrouteservice'.", field="provider")
    if profile is not None and (not isinstance(profile, str) or not profile.strip()):
        return _err("VALIDATION_ERROR", "profile must be a non-empty string when provided.", field="profile")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided.", field="idempotency_key")
    if vehicles is not None:
        if not isinstance(vehicles, int) or isinstance(vehicles, bool) or vehicles < 1:
            return _err("VALIDATION_ERROR", "vehicles must be an integer >= 1 when provided.", field="vehicles")
    else:
        vehicles = 1

    workspace, keyrow = _choose_context()
    if not workspace:
        return _err("UNAUTHORIZED", "No active workspace available to serve the request.")

    max_locs = _plan_max_locations(workspace.get("plan"))
    if not isinstance(delivery_locations, list):
        return _err("VALIDATION_ERROR", "delivery_locations must be an array.", field="delivery_locations")
    if len(delivery_locations) > max_locs:
        return _err("VALIDATION_ERROR", f"Too many delivery locations for plan '{workspace.get('plan')}'.", field="delivery_locations", max=max_locs)

    # Relaxed coordinate validation: accept empty placeholders and record failed operation rather than reject.
    depot_ok = False
    ve_dep = _validate_pair(depot_location, "depot_location", allow_empty_pair=True)
    if ve_dep is None and isinstance(depot_location, list) and len(depot_location) == 2 and _is_num(depot_location[0]) and _is_num(depot_location[1]):
        depot_ok = True

    valid_deliveries = []
    invalid_delivery_idx = []
    for i, loc in enumerate(delivery_locations):
        ve = _validate_pair(loc, "delivery_locations", index=i, allow_empty_pair=True)
        if ve is None and isinstance(loc, list) and len(loc) == 2 and _is_num(loc[0]) and _is_num(loc[1]):
            valid_deliveries.append([float(loc[0]), float(loc[1])])
        else:
            if ve is not None:
                invalid_delivery_idx.append(i)

    ops = _load("geo_operations.json")
    payloads = _load("provider_payloads.json")
    ledger = _load("usage_ledger.json")
    tool_name = "create_simple_delivery_problem"

    if idempotency_key is not None:
        for op in ops:
            if op.get("workspace_id") == workspace["id"] and op.get("tool_name") == tool_name and op.get("idempotency_key") == idempotency_key:
                ledger.append({
                    "id": _new_id("use"),
                    "workspace_id": workspace["id"],
                    "api_key_id": (keyrow.get("id") if keyrow else None),
                    "operation_id": None,
                    "tool_name": "adjustment",
                    "status": "posted",
                    "op_count": 0,
                    "provider_cost_usd": 0.0,
                    "occurred_at": now,
                    "month_bucket": month_bucket,
                    "created_at": now,
                    "updated_at": now,
                })
                _save("usage_ledger.json", ledger)
                return {
                    "operation": op,
                    "idempotent_replay": True,
                    "provider_response": next((p.get("payload_json") for p in payloads if p.get("operation_id") == op.get("id") and p.get("kind") == "response"), None),
                    "latency_ms": int((time.time() - _t0) * 1000),
                }

    estimated_cost = 0.008
    qe = _enforce_quota(workspace, ledger, add_ops=1, add_cost=estimated_cost, mb=month_bucket)
    if qe:
        op_id = _new_id("op")
        op_row = {
            "id": op_id,
            "workspace_id": workspace["id"],
            "api_key_id": (keyrow.get("id") if keyrow else None),
            "tool_name": tool_name,
            "status": "failed",
            "provider": provider or workspace.get("provider_default") or "openrouteservice",
            "provider_endpoint": "optimization",
            "requested_at": now,
            "started_at": now,
            "finished_at": now,
            "latency_ms": int((time.time() - _t0) * 1000),
            "error_code": "quota_exceeded",
            "error_message": qe["error"]["message"],
            "request_ip": None,
            "idempotency_key": idempotency_key,
            "input_text": None,
            "input_coordinates": None,
            "input_locations": None,
            "input_profile": profile,
            "input_range": None,
            "input_buffer_m": None,
            "input_limit": None,
            "input_filters": None,
            "input_jobs": None,
            "input_vehicles": None,
            "input_depot_location": depot_location,
            "input_delivery_locations": delivery_locations,
            "input_start_location": None,
            "input_end_location": None,
            "result_summary": None,
            "provider_http_status": None,
            "provider_request_id": None,
            "estimated_cost_usd": float(estimated_cost),
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op_row)
        _save("geo_operations.json", ops)
        ledger.append({
            "id": _new_id("use"),
            "workspace_id": workspace["id"],
            "api_key_id": (keyrow.get("id") if keyrow else None),
            "operation_id": None,
            "tool_name": "adjustment",
            "status": "posted",
            "op_count": 0,
            "provider_cost_usd": 0.0,
            "occurred_at": now,
            "month_bucket": month_bucket,
            "created_at": now,
            "updated_at": now,
        })
        _save("usage_ledger.json", ledger)
        return qe

    op_id = _new_id("op")
    provider_name = provider or workspace.get("provider_default") or "openrouteservice"
    op_row = {
        "id": op_id,
        "workspace_id": workspace["id"],
        "api_key_id": (keyrow.get("id") if keyrow else None),
        "tool_name": tool_name,
        "status": "queued",
        "provider": provider_name,
        "provider_endpoint": "optimization",
        "requested_at": now,
        "started_at": None,
        "finished_at": None,
        "latency_ms": None,
        "error_code": None,
        "error_message": None,
        "request_ip": None,
        "idempotency_key": idempotency_key,
        "input_text": None,
        "input_coordinates": None,
        "input_locations": None,
        "input_profile": profile,
        "input_range": None,
        "input_buffer_m": None,
        "input_limit": None,
        "input_filters": None,
        "input_jobs": None,
        "input_vehicles": None,
        "input_depot_location": depot_location,
        "input_delivery_locations": delivery_locations,
        "input_start_location": None,
        "input_end_location": None,
        "result_summary": None,
        "provider_http_status": None,
        "provider_request_id": None,
        "estimated_cost_usd": float(estimated_cost),
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op_row)

    payloads.append({
        "id": _new_id("pay"),
        "operation_id": op_id,
        "kind": "request",
        "content_type": "application/json",
        "payload_json": _redact({
            "depot_location": depot_location,
            "delivery_locations": delivery_locations,
            "vehicles": vehicles,
            "profile": profile,
        }, "standard"),
        "redaction_level": "standard",
        "created_at": now,
        "updated_at": now,
    })

    op_row["status"] = "running"
    op_row["started_at"] = now
    op_row["updated_at"] = now

    if (not depot_ok) or (len(valid_deliveries) < 1):
        op_row["status"] = "failed"
        op_row["finished_at"] = now
        op_row["latency_ms"] = int((time.time() - _t0) * 1000)
        op_row["error_code"] = "validation_invalid_locations"
        op_row["error_message"] = "Depot and at least one valid delivery location are required by provider."
        op_row["provider_http_status"] = 400
        resp_payload = {"error": {"message": op_row["error_message"], "invalid_delivery_indices": invalid_delivery_idx}}
    else:
        # Create a simple set of routes: split deliveries evenly among vehicles
        vcount = max(1, int(vehicles))
        routes = [[] for _ in range(vcount)]
        for i, loc in enumerate(valid_deliveries):
            routes[i % vcount].append(loc)
        resp_payload = {
            "routes": [{"vehicle": i + 1, "stops": [depot_location] + r + [depot_location]} for i, r in enumerate(routes)],
            "metadata": {"vehicles": vcount, "deliveries": len(valid_deliveries)}
        }
        op_row["status"] = "succeeded"
        op_row["finished_at"] = now
        op_row["latency_ms"] = int((time.time() - _t0) * 1000)
        op_row["provider_http_status"] = 200
        op_row["result_summary"] = {"vehicles": vcount, "deliveries": len(valid_deliveries), "routes": vcount}
        op_row["updated_at"] = now

    if not any(p.get("operation_id") == op_id and p.get("kind") == "response" for p in payloads):
        payloads.append({
            "id": _new_id("pay"),
            "operation_id": op_id,
            "kind": "response",
            "content_type": "application/json",
            "payload_json": _redact(resp_payload, "standard"),
            "redaction_level": "standard",
            "created_at": now,
            "updated_at": now,
        })

    _save("geo_operations.json", ops)
    _save("provider_payloads.json", payloads)

    if op_row["status"] in ("succeeded", "failed"):
        ledger = _load("usage_ledger.json")
        if _post_usage_once(ledger, workspace["id"], (keyrow.get("id") if keyrow else None), op_id, tool_name, estimated_cost):
            _save("usage_ledger.json", ledger)
        ledger.append({
            "id": _new_id("use"),
            "workspace_id": workspace["id"],
            "api_key_id": (keyrow.get("id") if keyrow else None),
            "operation_id": None,
            "tool_name": "adjustment",
            "status": "posted",
            "op_count": 0,
            "provider_cost_usd": 0.0,
            "occurred_at": now,
            "month_bucket": month_bucket,
            "created_at": now,
            "updated_at": now,
        })
        _save("usage_ledger.json", ledger)

    return {
        "operation": op_row,
        "provider_response": resp_payload,
        "latency_ms": int((time.time() - _t0) * 1000),
        "idempotent_replay": False,
    }

def get_me(api_key, **_extra):
    import json, os, datetime, time, base64, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0502000" if __import__("os").path.isdir("./environment_mix/0502000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _month_bucket(dt_iso):
        try:
            dt = datetime.datetime.fromisoformat(dt_iso.replace("Z", "+00:00"))
        except Exception:
            dt = datetime.datetime.now(datetime.timezone.utc)
        return f"{dt.year:04d}-{dt.month:02d}"

    def _normalize_scopes(s):
        if s is None:
            return None
        if isinstance(s, list):
            out = []
            for v in s:
                if isinstance(v, str):
                    out.append(v)
            return out
        return None

    def _hash_secret(secret):
        # Not used for auth; only for storing new keys (create_api_key). Included for completeness.
        return hashlib.sha256(secret.encode("utf-8")).hexdigest()

    def _log(endpoint, workspace_id, api_key_id, status, started_ts, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = time.time()
        latency_ms = int(max(0, (now - started_ts) * 1000))
        row = {
            "id": f"req_{secrets.token_hex(12)}",
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _authenticate(api_key_value):
        # Explicit credential parameter: must match client-visible value.
        # Store has only hashes; therefore accept either api_keys.id or api_keys.key_prefix as a fallback.
        # If api_key_value looks like a full key (contains '.'), match by prefix before '.'.
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            return None, None

        presented = api_key_value
        presented_prefix = None
        if isinstance(presented, str) and "." in presented:
            presented_prefix = presented.split(".", 1)[0]
        elif isinstance(presented, str) and len(presented) >= 6:
            presented_prefix = presented[:10]

        # Prefer exact id match
        candidates = []
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == presented:
                candidates.append(k)
        # Then prefix match
        if not candidates and presented_prefix:
            for k in keys:
                if not isinstance(k, dict):
                    continue
                if k.get("key_prefix") == presented_prefix:
                    candidates.append(k)

        # Choose an active one if possible
        for k in candidates:
            if k.get("status") == "active":
                ws_id = k.get("workspace_id")
                workspaces = _load("workspaces.json")
                ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
                if ws and ws.get("status") in ("active", "suspended", "deleted"):
                    return k, ws

        return None, None

    started = time.time()

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        _log("get_me", None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    key_row, ws_row = _authenticate(api_key.strip())
    if not key_row or not ws_row:
        _log("get_me", None, None, "UNAUTHORIZED", started)
        return _err("UNAUTHORIZED", "Invalid or missing API key")

    if key_row.get("status") != "active":
        _log("get_me", ws_row.get("id"), key_row.get("id"), "UNAUTHORIZED", started)
        return _err("UNAUTHORIZED", "API key is revoked")

    # Update last_used_at
    keys = _load("api_keys.json")
    if isinstance(keys, list):
        for k in keys:
            if isinstance(k, dict) and k.get("id") == key_row.get("id"):
                k["last_used_at"] = _now_iso()
                k["updated_at"] = _now_iso()
                key_row = k
                break
        _save("api_keys.json", keys)

    # Compute MTD usage
    now_iso = _now_iso()
    bucket = _month_bucket(now_iso)

    ledger = _load("usage_ledger.json")
    if not isinstance(ledger, list):
        ledger = []

    ws_id = ws_row.get("id")
    posted = [
        e for e in ledger
        if isinstance(e, dict)
        and e.get("workspace_id") == ws_id
        and e.get("status") == "posted"
        and e.get("month_bucket") == bucket
    ]
    op_used = 0
    cost_used = 0.0
    for e in posted:
        try:
            op_used += int(e.get("op_count", 0))
        except Exception:
            pass
        try:
            cost_used += float(e.get("provider_cost_usd", 0.0))
        except Exception:
            pass

    # Scopes are not in schema; return defaults.
    # Grant "keys:manage" only to keys whose name indicates admin/owner/manager (best-effort) since no field exists.
    name = (key_row.get("name") or "").lower()
    scopes = ["geocode", "directions", "isochrones", "pois", "optimization", "operations:read"]
    if any(tok in name for tok in ("admin", "owner", "manage", "manager")):
        scopes.append("keys:manage")

    resp = {
        "principal": {
            "api_key": {
                "id": key_row.get("id"),
                "name": key_row.get("name"),
                "status": key_row.get("status"),
                "key_prefix": key_row.get("key_prefix"),
                "workspace_id": key_row.get("workspace_id"),
                "last_used_at": key_row.get("last_used_at"),
                "created_at": key_row.get("created_at"),
                "updated_at": key_row.get("updated_at"),
                "scopes": scopes,
            },
            "workspace": ws_row,
        },
        "usage": {
            "month_bucket": bucket,
            "op_used": op_used,
            "op_limit": ws_row.get("monthly_op_limit"),
            "provider_cost_usd_used": cost_used,
            "provider_cost_usd_limit": ws_row.get("monthly_provider_cost_usd_limit"),
        },
    }

    _log("get_me", ws_id, key_row.get("id"), "OK", started)
    return resp

def list_workspaces(api_key, status=None, plan=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0502000" if __import__("os").path.isdir("./environment_mix/0502000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, workspace_id, api_key_id, status_s, started_ts, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(max(0, (time.time() - started_ts) * 1000))
        row = {
            "id": f"req_{secrets.token_hex(12)}",
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "status": status_s,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _authenticate(api_key_value):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            return None, None
        presented = api_key_value
        presented_prefix = None
        if isinstance(presented, str) and "." in presented:
            presented_prefix = presented.split(".", 1)[0]
        elif isinstance(presented, str) and len(presented) >= 6:
            presented_prefix = presented[:10]

        candidates = []
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == presented:
                candidates.append(k)
        if not candidates and presented_prefix:
            for k in keys:
                if not isinstance(k, dict):
                    continue
                if k.get("key_prefix") == presented_prefix:
                    candidates.append(k)

        for k in candidates:
            if k.get("status") == "active":
                ws_id = k.get("workspace_id")
                workspaces = _load("workspaces.json")
                ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
                if ws:
                    return k, ws
        return None, None

    started = time.time()

    if not isinstance(api_key, str) or not api_key.strip():
        _log("list_workspaces", None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    if status is not None and status not in ("active", "suspended", "deleted"):
        _log("list_workspaces", None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "Invalid status filter")

    if plan is not None and plan not in ("free", "pro", "enterprise"):
        _log("list_workspaces", None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "Invalid plan filter")

    if limit is None:
        limit_val = 50
    else:
        if not isinstance(limit, int):
            _log("list_workspaces", None, None, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            _log("list_workspaces", None, None, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
        limit_val = limit

    if cursor is not None and (not isinstance(cursor, str) or cursor == ""):
        _log("list_workspaces", None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")

    key_row, ws_row = _authenticate(api_key.strip())
    if not key_row or not ws_row:
        _log("list_workspaces", None, None, "UNAUTHORIZED", started)
        return _err("UNAUTHORIZED", "Invalid or missing API key")
    if key_row.get("status") != "active":
        _log("list_workspaces", ws_row.get("id"), key_row.get("id"), "UNAUTHORIZED", started)
        return _err("UNAUTHORIZED", "API key is revoked")

    # Update last_used_at
    keys = _load("api_keys.json")
    if isinstance(keys, list):
        for k in keys:
            if isinstance(k, dict) and k.get("id") == key_row.get("id"):
                k["last_used_at"] = _now_iso()
                k["updated_at"] = _now_iso()
                key_row = k
                break
        _save("api_keys.json", keys)

    # Visibility model: key sees only its own workspace (no org/users model in schema).
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    visible = [w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_row.get("id")]

    # Filters
    if status is not None:
        visible = [w for w in visible if w.get("status") == status]
    if plan is not None:
        visible = [w for w in visible if w.get("plan") == plan]

    # Deterministic order: by created_at then id
    def _key(w):
        return (w.get("created_at") or "", w.get("id") or "")
    visible.sort(key=_key)

    # Cursor is opaque: use "idx:<n>"
    start_idx = 0
    if cursor:
        if not cursor.startswith("idx:"):
            _log("list_workspaces", ws_row.get("id"), key_row.get("id"), "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "Invalid cursor")
        try:
            start_idx = int(cursor.split(":", 1)[1])
        except Exception:
            _log("list_workspaces", ws_row.get("id"), key_row.get("id"), "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "Invalid cursor")
        if start_idx < 0:
            start_idx = 0

    total = len(visible)
    page = visible[start_idx:start_idx + limit_val]
    next_idx = start_idx + len(page)
    has_more = next_idx < total
    next_cursor = f"idx:{next_idx}" if has_more else None

    _log("list_workspaces", ws_row.get("id"), key_row.get("id"), "OK", started)
    return {
        "workspaces": page,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "limit": limit_val,
    }

