        latency_ms = int(max(0, (time.time() - started_ts) * 1000))
        row = {
            "id": f"req_{secrets.token_hex(12)}",
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "status": status_s,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _authenticate(api_key_value):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            return None, None
        presented = api_key_value
        presented_prefix = None
        if isinstance(presented, str) and "." in presented:
            presented_prefix = presented.split(".", 1)[0]
        elif isinstance(presented, str) and len(presented) >= 6:
            presented_prefix = presented[:10]

        candidates = []
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == presented:
                candidates.append(k)
        if not candidates and presented_prefix:
            for k in keys:
                if not isinstance(k, dict):
                    continue
                if k.get("key_prefix") == presented_prefix:
                    candidates.append(k)

        for k in candidates:
            if k.get("status") == "active":
                ws_id = k.get("workspace_id")
                workspaces = _load("workspaces.json")
                ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
                if ws:
                    return k, ws
        return None, None

    started = time.time()

    # Validate basic inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log("update_workspace", None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        _log("update_workspace", None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    if status is not None and status not in ("active", "suspended", "deleted"):
        _log("update_workspace", None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "Invalid status")
    if provider_default is not None and provider_default not in ("openrouteservice",):
        _log("update_workspace", None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "Invalid provider_default")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        _log("update_workspace", None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided")
    if provider_account_ref is not None and not isinstance(provider_account_ref, str):
        _log("update_workspace", None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "provider_account_ref must be a string when provided")
    if monthly_op_limit is not None:
        if not isinstance(monthly_op_limit, int) or monthly_op_limit < 0:
            _log("update_workspace", None, None, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "monthly_op_limit must be an integer >= 0")
    if monthly_provider_cost_usd_limit is not None:
        if not isinstance(monthly_provider_cost_usd_limit, (int, float)) or float(monthly_provider_cost_usd_limit) < 0:
            _log("update_workspace", None, None, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "monthly_provider_cost_usd_limit must be a number >= 0")

    key_row, caller_ws = _authenticate(api_key.strip())
    if not key_row or not caller_ws:
        _log("update_workspace", None, None, "UNAUTHORIZED", started)
        return _err("UNAUTHORIZED", "Invalid or missing API key")
    if key_row.get("status") != "active":
        _log("update_workspace", caller_ws.get("id"), key_row.get("id"), "UNAUTHORIZED", started)
        return _err("UNAUTHORIZED", "API key is revoked")

    # Update last_used_at
    keys = _load("api_keys.json")
    if isinstance(keys, list):
        for k in keys:
            if isinstance(k, dict) and k.get("id") == key_row.get("id"):
                k["last_used_at"] = _now_iso()
                k["updated_at"] = _now_iso()
                key_row = k
                break
        _save("api_keys.json", keys)

    # Authorization: can only update own workspace (no cross-workspace perms modeled)
    if caller_ws.get("id") != id.strip():
        _log("update_workspace", caller_ws.get("id"), key_row.get("id"), "UNAUTHORIZED", started)
        return _err("UNAUTHORIZED", "API key not authorized for this workspace")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    idx = None
    ws = None
    for i, w in enumerate(workspaces):
        if isinstance(w, dict) and w.get("id") == id.strip():
            idx = i
            ws = w
            break
    if ws is None:
        _log("update_workspace", caller_ws.get("id"), key_row.get("id"), "NOT_FOUND", started)
        return _err("NOT_FOUND", "Workspace not found")

    if ws.get("status") == "deleted":
        _log("update_workspace", ws.get("id"), key_row.get("id"), "CONFLICT", started)
        return _err("CONFLICT", "Cannot update a deleted workspace")

    # Enforce unique(name)
    if name is not None:
        for w in workspaces:
            if isinstance(w, dict) and w.get("id") != ws.get("id") and w.get("name") == name:
                _log("update_workspace", ws.get("id"), key_row.get("id"), "CONFLICT", started)
                return _err("CONFLICT", "Workspace name must be unique")

    # Lifecycle transitions
    if status is not None and status != ws.get("status"):
        transitions = {
            "active": ["suspended", "deleted"],
            "suspended": ["active", "deleted"],
            "deleted": [],
        }
        cur = ws.get("status")
        allowed = transitions.get(cur, [])
        if status not in allowed:
            _log("update_workspace", ws.get("id"), key_row.get("id"), "INVALID_TRANSITION", started)
            return _err("INVALID_TRANSITION", f"Cannot transition workspace status from {cur} to {status}")

    # Apply updates
    changed = False
    if name is not None and name != ws.get("name"):
        ws["name"] = name
        changed = True
    if status is not None and status != ws.get("status"):
        ws["status"] = status
        changed = True
    if provider_default is not None and provider_default != ws.get("provider_default"):
        ws["provider_default"] = provider_default
        changed = True
    if provider_account_ref is not None and provider_account_ref != ws.get("provider_account_ref"):
        ws["provider_account_ref"] = provider_account_ref
        changed = True
    if monthly_op_limit is not None and monthly_op_limit != ws.get("monthly_op_limit"):
        ws["monthly_op_limit"] = monthly_op_limit
        changed = True
    if monthly_provider_cost_usd_limit is not None and float(monthly_provider_cost_usd_limit) != float(ws.get("monthly_provider_cost_usd_limit", 0.0)):
        ws["monthly_provider_cost_usd_limit"] = float(monthly_provider_cost_usd_limit)
        changed = True

    if not changed:
        # Still a successful "no-op" update is acceptable in many APIs, but must reflect real behavior.
        # Return current workspace.
        _log("update_workspace", ws.get("id"), key_row.get("id"), "OK", started, {"note": "no_changes"})
        return {"workspace": ws}

    ws["updated_at"] = _now_iso()
    workspaces[idx] = ws
    _save("workspaces.json", workspaces)

    _log("update_workspace", ws.get("id"), key_row.get("id"), "OK", started)
    return {"workspace": ws}

def create_api_key(api_key, workspace_id, name, scopes=None, **_extra):
    import json, os, datetime, time, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0502000" if __import__("os").path.isdir("./environment_mix/0502000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
           	    return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, workspace_id_v, api_key_id, status_s, started_ts, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(max(0, (time.time() - started_ts) * 1000))
        row = {
            "id": f"req_{secrets.token_hex(12)}",
            "endpoint": endpoint,
            "workspace_id": workspace_id_v,
            "api_key_id": api_key_id,
            "status": status_s,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _authenticate(api_key_value):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            return None, None
        presented = api_key_value
        presented_prefix = None
        if isinstance(presented, str) and "." in presented:
            presented_prefix = presented.split(".", 1)[0]
        elif isinstance(presented, str) and len(presented) >= 6:
            presented_prefix = presented[:10]

        candidates = []
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == presented:
                candidates.append(k)
        if not candidates and presented_prefix:
            for k in keys:
                if not isinstance(k, dict):
                    continue
                if k.get("key_prefix") == presented_prefix:
                    candidates.append(k)

        for k in candidates:
            if k.get("status") == "active":
                ws_id = k.get("workspace_id")
                workspaces = _load("workspaces.json")
                ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
                if ws:
                    return k, ws
        return None, None

    def _sha256_hex(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    started = time.time()

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log("create_api_key", None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(workspace_id, str) or not workspace_id.strip():
        _log("create_api_key", None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string")
    if not isinstance(name, str) or not name.strip():
        _log("create_api_key", None, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "name must be a non-empty string")

    allowed_scopes = {"geocode", "directions", "isochrones", "pois", "optimization", "operations:read", "keys:manage"}
    if scopes is not None:
        if not isinstance(scopes, list) or any((not isinstance(s, str) or s not in allowed_scopes) for s in scopes):
            _log("create_api_key", None, None, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "Invalid scopes")

    key_row, caller_ws = _authenticate(api_key.strip())
    if not key_row or not caller_ws:
        _log("create_api_key", None, None, "UNAUTHORIZED", started)
        return _err("UNAUTHORIZED", "Invalid or missing API key")
    if key_row.get("status") != "active":
        _log("create_api_key", caller_ws.get("id"), key_row.get("id"), "UNAUTHORIZED", started)
        return _err("UNAUTHORIZED", "API key is revoked")

    # Update last_used_at
    keys_all = _load("api_keys.json")
    if isinstance(keys_all, list):
        for k in keys_all:
            if isinstance(k, dict) and k.get("id") == key_row.get("id"):
                k["last_used_at"] = _now_iso()
                k["updated_at"] = _now_iso()
                key_row = k
                break
        _save("api_keys.json", keys_all)

    # Authorization: can only create keys in own workspace unless caller is "keys:manage" capable (inferred by name)
    caller_name = (key_row.get("name") or "").lower()
    can_manage = any(tok in caller_name for tok in ("admin", "owner", "manage", "manager"))
    if caller_ws.get("id") != workspace_id.strip() and not can_manage:
        _log("create_api_key", caller_ws.get("id"), key_row.get("id"), "UNAUTHORIZED", started)
        return _err("UNAUTHORIZED", "API key not authorized to create keys for this workspace")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    target_ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id.strip()), None)
    if not target_ws:
        _log("create_api_key", caller_ws.get("id"), key_row.get("id"), "NOT_FOUND", started)
        return _err("NOT_FOUND", "Workspace not found")

    # Business rule: refuse when workspace suspended/deleted
    if target_ws.get("status") in ("suspended", "deleted"):
        _log("create_api_key", target_ws.get("id"), key_row.get("id"), "UNAUTHORIZED", started, {"detail": "workspace_not_active"})
        return _err("UNAUTHORIZED", "Workspace is not active")

    # Limits exceeded: no explicit schema; implement a reasonable cap by plan.
    plan = target_ws.get("plan")
    plan_caps = {"free": 2, "pro": 10, "enterprise": 100}
    cap = plan_caps.get(plan, 2)

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    existing_for_ws = [k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == target_ws.get("id") and k.get("status") == "active"]
    if len(existing_for_ws) >= cap:
        _log("create_api_key", target_ws.get("id"), key_row.get("id"), "QUOTA_EXCEEDED", started, {"cap": cap})
        return _err("QUOTA_EXCEEDED", "API key limit exceeded for workspace", limit=cap)

    # unique(workspace_id, name)
    for k in api_keys:
        if isinstance(k, dict) and k.get("workspace_id") == target_ws.get("id") and k.get("name") == name:
            _log("create_api_key", target_ws.get("id"), key_row.get("id"), "CONFLICT", started)
            return _err("CONFLICT", "API key name must be unique within workspace")

    # Generate key material once; store hash and prefix.
    prefix = f"gp_{secrets.token_hex(4)}"  # length >= 6
    secret = secrets.token_urlsafe(24)
    key_material = f"{prefix}.{secret}"

    key_hash = _sha256_hex(key_material)
    # unique(key_hash)
    for k in api_keys:
        if isinstance(k, dict) and k.get("key_hash") == key_hash:
            # extremely unlikely; regenerate once
            secret = secrets.token_urlsafe(24)
            key_material = f"{prefix}.{secret}"
            key_hash = _sha256_hex(key_material)
            break
    for k in api_keys:
        if isinstance(k, dict) and k.get("key_hash") == key_hash:
            _log("create_api_key", target_ws.get("id"), key_row.get("id"), "CONFLICT", started)
            return _err("CONFLICT", "Could not generate a unique API key")

    new_id = f"key_{secrets.token_hex(12)}"
    now = _now_iso()
    row = {
        "id": new_id,
        "workspace_id": target_ws.get("id"),
        "name": name,
        "key_hash": key_hash,
        "key_prefix": prefix,
        "status": "active",
        "last_used_at": None,
        "created_at": now,
        "updated_at": now,
    }
    api_keys.append(row)
    _save("api_keys.json", api_keys)

    # Note: scopes are not persisted in schema; return them in response only.
    returned_scopes = scopes if scopes is not None else ["geocode", "directions", "isochrones", "pois", "optimization", "operations:read"]

    _log("create_api_key", target_ws.get("id"), key_row.get("id"), "OK", started)
    return {
        "api_key": {
            **row,
            "scopes": returned_scopes,
        },
        "key_material": key_material,  # returned exactly once
    }

