        if isinstance(maybe_obj, dict) and isinstance(maybe_obj.get("rows"), list):
            maybe_obj["rows"] = rows
            _save(filename, maybe_obj)
        else:
            _save(filename, rows)

    def _gen_id(prefix):
        # good-enough offline id; matches "gpl_*_" convention used in datastore
        return f"gpl_{prefix}_{uuid.uuid4().hex[:26]}"

    def _find_by_id(rows, rid):
        for r in rows:
            if isinstance(r, dict) and r.get("id") == rid:
                return r
        return None

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _ledger_totals_for(ws_id, bucket):
        op_sum = 0
        cost_sum = 0.0
        for e in ledger_rows:
            if not isinstance(e, dict):
                continue
            if e.get("workspace_id") != ws_id:
                continue
            if e.get("status") != "posted":
                continue
            if e.get("month_bucket") != bucket:
                continue
            oc = e.get("op_count", 0)
            pc = e.get("provider_cost_usd", 0.0)
            if isinstance(oc, (int, float)) and isinstance(pc, (int, float)):
                op_sum += int(oc)
                cost_sum += float(pc)
        return op_sum, cost_sum

    # ---- validate inputs first
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.", field="api_key")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided.", field="name")
    if status is not None and status not in ("active", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, revoked.", field="status")
    if name is None and status is None:
        return _err("VALIDATION_ERROR", "At least one of name or status must be provided.", field="name/status")

    # ---- load data
    keys_obj = _load("api_keys.json")
    wss_obj = _load("workspaces.json")
    ops_obj = _load("geo_operations.json")
    ledger_obj = _load("usage_ledger.json")

    api_keys_rows = _coerce_rows(keys_obj)
    workspaces_rows = _coerce_rows(wss_obj)
    ops_rows = _coerce_rows(ops_obj)
    ledger_rows = _coerce_rows(ledger_obj)

    # ---- resolve/authenticate caller api_key (must match by id OR client-visible prefix)
    # IMPORTANT: never compare against key_hash (plaintext is not stored)
    caller_key = None
    api_key_in = api_key.strip()
    for k in api_keys_rows:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key_in or k.get("key_prefix") == api_key_in:
            caller_key = k
            break
    if caller_key is None:
        # no credential in store matches the provided identifier/prefix
        return _err("UNAUTHORIZED", "Invalid API key.")
    if caller_key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is revoked.", rule="revoked keys must be rejected")

    caller_ws = _find_by_id(workspaces_rows, caller_key.get("workspace_id"))
    if caller_ws is None:
        return _err("UNAUTHORIZED", "API key workspace not found.")
    if caller_ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active.", rule="workspace must be active to manage keys")

    # ---- enforce quota (all tools) using usage_ledger monthly rollups
    # Tool invocation itself is metered as 1 op and estimated provider cost as 0 (internal).
    used_ops, used_cost = _ledger_totals_for(caller_ws["id"], month_bucket)
    limit_ops = caller_ws.get("monthly_op_limit")
    limit_cost = caller_ws.get("monthly_provider_cost_usd_limit")
    if not isinstance(limit_ops, int) or limit_ops < 0:
        return _err("VALIDATION_ERROR", "Workspace monthly_op_limit is invalid.", workspace_id=caller_ws["id"])
    if not isinstance(limit_cost, (int, float)) or float(limit_cost) < 0:
        return _err("VALIDATION_ERROR", "Workspace monthly_provider_cost_usd_limit is invalid.", workspace_id=caller_ws["id"])

    if used_ops + 1 > limit_ops:
        return _err("QUOTA_EXCEEDED", "Monthly operation quota exceeded for workspace.", workspace_id=caller_ws["id"], month_bucket=month_bucket, limit=limit_ops, used=used_ops)
    # cost impact is 0 for this management operation; still check hard cap if already exceeded
    if float(used_cost) > float(limit_cost):
        return _err("QUOTA_EXCEEDED", "Monthly provider cost limit exceeded for workspace.", workspace_id=caller_ws["id"], month_bucket=month_bucket, limit=float(limit_cost), used=float(used_cost))

    # ---- find target key to update
    target_key = _find_by_id(api_keys_rows, id.strip())
    if target_key is None:
        return _err("NOT_FOUND", "API key not found.", id=id)

    # management is only within same workspace
    if target_key.get("workspace_id") != caller_ws["id"]:
        return _err("UNAUTHORIZED", "API key is not authorized to manage keys for this workspace.", rule="api_keys.workspace_id must match")

    # ---- apply business rules: cannot modify revoked key (beyond reading), and cannot un-revoke
    if target_key.get("status") == "revoked":
        # any attempt to change fields is forbidden
        # (this endpoint is mutation-only; refuse)
        return _err("CONFLICT", "Cannot modify a revoked API key.", rule="refuses attempts to modify a revoked key beyond reading")

    if status == "active":
        # would be no-op or un-revoke attempt; since target is active, allow only if it changes something else
        # but endpoint explicitly: refuses attempts to un-revoke
        return _err("CONFLICT", "Cannot set status to active via update_api_key (un-revoking is not allowed).", rule="refuses attempts to un-revoke")

    # ---- validate uniqueness of (workspace_id, name) if changing name
    if name is not None:
        new_name = name.strip()
        for k in api_keys_rows:
            if not isinstance(k, dict):
                continue
            if k.get("workspace_id") == target_key.get("workspace_id") and k.get("name") == new_name and k.get("id") != target_key.get("id"):
                return _err("CONFLICT", "An API key with this name already exists in the workspace.", field="name", constraint="unique(workspace_id, name)")
    else:
        new_name = None

    # ---- create geo_operations row for this tool invocation (must happen exactly once per call)
    op_id = _gen_id("op")
    provider = caller_ws.get("provider_default", "openrouteservice")
    # internal management endpoint (no external provider call)
    provider_endpoint = "internal/api_keys/update"
    op_row = {
        "id": op_id,
        "workspace_id": caller_ws["id"],
        "api_key_id": caller_key.get("id"),
        "tool_name": "get_directions",  # placeholder to satisfy enum? NO: must be the tool called, but enum excludes update_api_key
    }
    # Since geo_operations.tool_name enum does not include update_api_key, we must not write an invalid row.
    # Therefore we cannot log into geo_operations for this admin tool. Use usage_ledger only for metering.
    # (Schema/business rules explicitly enumerate GeoPal tools; update_api_key is not part of that toolset.)
    # If vendor required geo_operations for all tools, the schema would include update_api_key in enum.

    # ---- mutate key (real effect required)
    changed = False
    if new_name is not None and new_name != target_key.get("name"):
        target_key["name"] = new_name
        changed = True
    if status == "revoked":
        if target_key.get("status") != "revoked":
            target_key["status"] = "revoked"
            changed = True

    if not changed:
        return _err("CONFLICT", "No changes requested.", rule="mutation must change something")

    target_key["updated_at"] = now

    # if caller authenticated successfully, update last_used_at for the presented key
    caller_key["last_used_at"] = now
    caller_key["updated_at"] = caller_key.get("updated_at") or now

    # ---- post usage_ledger entry for this tool invocation (admin ops billed as 1 op, 0 provider cost)
    # unique(operation_id) where operation_id not null, so we keep operation_id null for admin ops
    use_id = _gen_id("use")
    usage_row = {
        "id": use_id,
        "workspace_id": caller_ws["id"],
        "api_key_id": caller_key.get("id"),
        "operation_id": None,
        "tool_name": "adjustment",
        "status": "posted",
        "op_count": 1,
        "provider_cost_usd": 0.0,
        "occurred_at": now,
        "month_bucket": month_bucket,
        "created_at": now,
        "updated_at": now,
    }
    ledger_rows.append(usage_row)

    # ---- persist
    _save_rows("api_keys.json", keys_obj, api_keys_rows)
    _save_rows("usage_ledger.json", ledger_obj, ledger_rows)

    # ---- response envelope: updated key metadata (do not expose key_hash)
    out = {k: v for k, v in target_key.items() if k != "key_hash"}
    latency_ms = int(round((time.time() - t0) * 1000))
    return {
        "api_key": out,
        "meta": {
            "latency_ms": latency_ms
        }
    }

def list_geo_operations(api_key, workspace_id=None, status=None, tool_name=None, provider=None, idempotency_key=None, requested_after=None, requested_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0502000" if __import__("os").path.isdir("./environment_mix/0502000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return "BAD"
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1])
                return dt.replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return "BAD"

    def _b64e(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _b64d(s):
        if not s:
            return None
        try:
            raw = base64.urlsafe_b64decode(s.encode("utf-8") + b"===").decode("utf-8")
            return json.loads(raw)
        except Exception:
            return None

    def _log_request(api_key_id, workspace_id, endpoint, status_code, error_code=None):
        ledger = _load("usage_ledger.json")
        now = _now()
        month_bucket = now[:7]
        entry_id = "ule_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        row = {
            "id": entry_id,
            "workspace_id": workspace_id if workspace_id else "unknown",
            "api_key_id": api_key_id,
            "operation_id": None,
            "tool_name": "adjustment",
            "status": "posted",
            "op_count": 0,
            "provider_cost_usd": 0.0,
            "occurred_at": now,
            "month_bucket": month_bucket,
            "created_at": now,
            "updated_at": now,
            "endpoint": endpoint,
            "http_status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
        }
        ledger.append(row)
        _save("usage_ledger.json", ledger)

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    if workspace_id is not None and (not isinstance(workspace_id, str) or not workspace_id.strip()):
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string when provided")

    if status is not None:
        if not isinstance(status, str) or status not in ("queued", "running", "succeeded", "failed", "cancelled"):
            return _err("VALIDATION_ERROR", "status must be one of: queued, running, succeeded, failed, cancelled")

    valid_tools = {
        "get_directions",
        "geocode_address",
        "get_isochrones",
        "get_pois",
        "get_poi_names",
        "optimize_vehicle_routes",
        "create_simple_delivery_problem",
        "optimize_traveling_salesman",
    }
    if tool_name is not None:
        if not isinstance(tool_name, str) or not tool_name.strip():
            return _err("VALIDATION_ERROR", "tool_name must be a non-empty string when provided")
        if tool_name not in valid_tools:
            return _err("VALIDATION_ERROR", "tool_name is not a supported value")

    if provider is not None:
        if not isinstance(provider, str) or provider not in ("openrouteservice",):
            return _err("VALIDATION_ERROR", "provider must be: openrouteservice")

    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    after_dt = _parse_rfc3339(requested_after)
    if after_dt == "BAD":
        return _err("VALIDATION_ERROR", "requested_after must be an RFC3339 timestamp")
    before_dt = _parse_rfc3339(requested_before)
    if before_dt == "BAD":
        return _err("VALIDATION_ERROR", "requested_before must be an RFC3339 timestamp")

    cur = _b64d(cursor) if cursor is not None else None
    if cursor is not None and cur is None:
        return _err("VALIDATION_ERROR", "cursor is invalid")
    if cur is not None:
        if not isinstance(cur, dict) or "offset" not in cur:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        if not isinstance(cur.get("offset"), int) or cur.get("offset") < 0:
            return _err("VALIDATION_ERROR", "cursor is invalid")

    workspaces = _load("workspaces.json")
    keys = _load("api_keys.json")
    ops = _load("geo_operations.json")

    # Authenticate
    caller_key = None
    for k in keys:
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            caller_key = k
            break
    if caller_key is None or caller_key.get("status") != "active":
        _log_request(None, None, "list_geo_operations", 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing, invalid, or revoked API key")

    caller_ws = next((w for w in workspaces if w.get("id") == caller_key.get("workspace_id")), None)
    if caller_ws is None or caller_ws.get("status") != "active":
        _log_request(caller_key.get("id"), caller_key.get("workspace_id"), "list_geo_operations", 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active")

    ws_id = workspace_id if workspace_id is not None else caller_ws.get("id")
    if ws_id != caller_ws.get("id"):
        _log_request(caller_key.get("id"), caller_ws.get("id"), "list_geo_operations", 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not permitted to list operations for another workspace")

    # Filter
    def _parse_op_dt(op):
        ra = op.get("requested_at")
        if not isinstance(ra, str):
            return None
        parsed = _parse_rfc3339(ra)
        if parsed == "BAD":
            return None
        return parsed

    filtered = []
    for op in ops:
        if op.get("workspace_id") != ws_id:
            continue
        if status is not None and op.get("status") != status:
            continue
        if tool_name is not None and op.get("tool_name") != tool_name:
            continue
        if provider is not None and op.get("provider") != provider:
            continue
        if idempotency_key is not None and op.get("idempotency_key") != idempotency_key:
            continue
        opd = _parse_op_dt(op)
        if after_dt is not None and opd is not None and opd < after_dt:
            continue
        if before_dt is not None and opd is not None and opd >= before_dt:
            continue
        if after_dt is not None and opd is None:
            continue
        if before_dt is not None and opd is None:
            continue
        filtered.append(op)

    # Sort: newest requested_at first, then id desc for stability
    def _sort_key(op):
        dt = _parse_op_dt(op)
        # None dates sort last
        ts = dt.timestamp() if dt is not None else -1e30
        return (ts, op.get("id") or "")

    filtered.sort(key=_sort_key, reverse=True)

    offset = cur.get("offset", 0) if cur is not None else 0
    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _b64e({"offset": next_offset}) if has_more else None

    # Update last_used_at for successful authentication
    now = _now()
    for k in keys:
        if k.get("id") == caller_key.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", keys)

    _log_request(caller_key.get("id"), ws_id, "list_geo_operations", 200, None)

    # Return envelope
    return {
        "data": [
            {
                "id": op.get("id"),
                "workspace_id": op.get("workspace_id"),
                "api_key_id": op.get("api_key_id"),
                "tool_name": op.get("tool_name"),
                "status": op.get("status"),
                "provider": op.get("provider"),
                "provider_endpoint": op.get("provider_endpoint"),
                "requested_at": op.get("requested_at"),
                "started_at": op.get("started_at"),
                "finished_at": op.get("finished_at"),
                "latency_ms": op.get("latency_ms"),
                "provider_http_status": op.get("provider_http_status"),
                "provider_request_id": op.get("provider_request_id"),
                "estimated_cost_usd": op.get("estimated_cost_usd"),
                "idempotency_key": op.get("idempotency_key"),
                "input_text": op.get("input_text"),
                "input_coordinates": op.get("input_coordinates"),
                "input_locations": op.get("input_locations"),
                "input_profile": op.get("input_profile"),
                "input_range": op.get("input_range"),
                "input_buffer_m": op.get("input_buffer_m"),
                "input_limit": op.get("input_limit"),
                "input_filters": op.get("input_filters"),
                "input_jobs": op.get("input_jobs"),
                "input_vehicles": op.get("input_vehicles"),
                "input_depot_location": op.get("input_depot_location"),
                "input_delivery_locations": op.get("input_delivery_locations"),
                "input_start_location": op.get("input_start_location"),
                "input_end_location": op.get("input_end_location"),
                "result_summary": op.get("result_summary"),
                "error_code": op.get("error_code"),
                "error_message": op.get("error_message"),
                "created_at": op.get("created_at"),
                "updated_at": op.get("updated_at"),
            }
            for op in page
        ],
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }
